acl_policies.default-ceiling:
# Allow an entity to inspect its own registration information
path "agent-registry/registration/entity_id/{{identity.entity.id}}" {
  capabilities = ["read"]
}

# Allow an entity to read the default policies
path "policy/default" {
  capabilities = ["read"]
}
path "policy/default-ceiling" {
  capabilities = ["read"]
}

acl_policies.eso-ewallet-reader:
# The only External Secrets Operator reader (ClusterSecretStore ewallet-vault, role eso-ewallet-reader).
# Read only, on two explicit prefixes. No list and no metadata, so the reader cannot discover
# paths; no system paths, no write. A new area (for example mcp-platform/) is a reviewed change here.
path "ewallet/data/ml-platform/*" {
  capabilities = ["read"]
}
path "ewallet/data/agent-platform/*" {
  capabilities = ["read"]
}

# token_no_default_policy removes these; ESO checks its login token and revokes it after use.
path "auth/token/lookup-self" {
  capabilities = ["read"]
}
path "auth/token/revoke-self" {
  capabilities = ["update"]
}

acl_policies.eso-vault-rehearsal:
# Rehearsal only (docs/runbooks/edai2/VAULT_GKE_REHEARSAL.md): ClusterSecretStore ewallet-vault-rehearsal,
# used from the temporary rehearsal namespaces, reads exactly three synthetic entries. They lie under the
# official prefixes, which the existing secret-operator token may write, so the rehearsal seeds them exactly
# like the official campaign (put --token-file). The real ml-platform/feast-online-redis,
# agent-platform/vllm-api-key and agent-platform/agentgateway-client-key are NOT readable here.
path "ewallet/data/ml-platform/rehearsal-redis" {
  capabilities = ["read"]
}
path "ewallet/data/agent-platform/rehearsal-vllm-api-key" {
  capabilities = ["read"]
}
path "ewallet/data/agent-platform/rehearsal-agentgateway-client-key" {
  capabilities = ["read"]
}

# token_no_default_policy removes these; ESO checks its login token and revokes it after use.
path "auth/token/lookup-self" {
  capabilities = ["read"]
}
path "auth/token/revoke-self" {
  capabilities = ["update"]
}

acl_policies.root-generation:
# Vault 2.x authenticates root generation. This policy lets the owner's admin login
# (role vault-admin) start, read, cancel and feed a root-generation ceremony, and nothing
# else: no secrets, no policies, no roles. Completing the ceremony still needs 2 of the
# 3 unseal shares. Never attach it to ESO readers or application roles.
path "sys/generate-root/attempt" {
  capabilities = ["create", "read", "update", "delete"]
}
path "sys/generate-root/update" {
  capabilities = ["create", "update"]
}

acl_policies.secret-operator:
# Rotation by a human operator: write new versions and read metadata, never values.
# The two V2 areas only (docs/edai2/platform/VAULT_V2_ARCHITECTURE_AUDIT.md §10).
path "ewallet/data/ml-platform/*" {
  capabilities = ["create", "update"]
}
path "ewallet/metadata/ml-platform/*" {
  capabilities = ["read", "list"]
}
path "ewallet/data/agent-platform/*" {
  capabilities = ["create", "update"]
}
path "ewallet/metadata/agent-platform/*" {
  capabilities = ["read", "list"]
}
